// Purpose: ROW-029, ROW-030, ROW-130 and ROW-131 (REQ-015, REQ-016) — on the checker page: Copy text
// puts exactly the box's current text, replacements included, on the clipboard and confirms it; with
// clipboard access refused it selects the whole text and names Ctrl+C (Cmd+C on a Mac) — on a touch
// phone, the long-press Copiar action — without claiming a copy; and copying from the box while
// highlights show puts only the plain text, equal to the box's text, on the clipboard.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, dictionary-es
// 4.0.0 pinned by SHA-256) and the harness's fresh markers, with a fresh seed per run; the clipboard is
// read with the browser's own paste in a scratch page; the refusal is the harness's browser fake.
//
// Test argument
// ROW-029 promise: Copy text puts exactly the box's current text, replacements included, on the
//   clipboard and shows a confirmation (REQ-015 fail-if: the clipboard differs by any character, a
//   replacement is missing, or no confirmation; A-006, A-019).
// ROW-029 wrong product: a Copy that copies the text as it was when checked (before the Replace), or
//   the text with its highlight markup or with trimmed lines, or that copies silently.
// ROW-029 given: a fresh sentinel already on the clipboard; a text with two fresh misspellings,
//   checked, one replaced by its first suggestion; when: Copy text is pressed; then: the clipboard's
//   plain text is exactly the box's text, which is the entered text with only that word replaced,
//   and the message element says it was copied — and before the press the clipboard held the
//   sentinel and no message said so.
// ROW-029 controls: the clipboard probe round-trips a fresh sentinel exactly in this engine — the
//   reading of the clipboard works; untouched by the product.
// ROW-029 technique: before/after on the clipboard (a fresh sentinel replaced), the expected text the
//   test's own model.
// cases: ROW-029 target=ROW-029-copy-text-puts-exactly-the-box-text-with-replacements-on-the-clipboard-and-confirms control=ROW-029-control-the-clipboard-probe-round-trips-a-sentinel
//
// ROW-030 promise: with clipboard access refused, Copy text selects all the text, tells the writer to
//   press Ctrl+C (Cmd+C on a Mac), and does not claim the text was copied (REQ-016 fail-if: no
//   message, nothing selected, or a claim of copying; A-019).
// ROW-030 wrong product: a Copy that calls the clipboard and shows "Texto copiado" without waiting
//   for the refusal, or shows an error and selects nothing.
// ROW-030 given: a keyboard device (in the phone project, a desktop context of the same engine) whose
//   browser refuses every clipboard write the page attempts; a fresh text in the box; when: Copy text
//   is pressed; then: the box's selection is its whole text, the message names Ctrl+C — or Cmd+C
//   when the device presents itself as a Mac (either, when its platform and user agent disagree) —
//   and the message does not say the text was copied.
// ROW-030 controls: from the page, a clipboard write is refused (the fake is in place) — the refused
//   case is reached; untouched by the product.
// ROW-030 technique: a fake for the external party (the browser's clipboard permission), the
//   writer's view read on named elements.
// cases: ROW-030 target=ROW-030-with-the-clipboard-refused-copy-text-selects-all-and-names-ctrl-c-without-claiming-a-copy control=ROW-030-control-the-browser-fake-refuses-a-clipboard-write
//
// ROW-130 promise: copying from the box by keyboard, context menu or touch while highlights show puts
//   on the clipboard only the plain text, equal to the box's text (origin: domain; REQ-015, REQ-016).
// ROW-130 wrong product: an editable box with <mark> highlights inside, whose native copy puts the
//   highlight markup (text/html with backgrounds) on the clipboard, or zero-width markers in the text.
// ROW-130 given: a fresh sentinel on the clipboard; a text with two fresh misspellings, checked, the
//   highlights showing; when: the box is focused, its text selected with Ctrl/Cmd+A and copied with
//   Ctrl/Cmd+C (the copy command a context-menu or touch Copy also runs — this test's limit: the
//   native menus themselves are not pressed); then: the clipboard's plain text is exactly the text
//   entered, and pasted into a rich editor it brings no formatting.
// ROW-130 controls: the check shows the highlights — the state the row is about is reached;
//   untouched by a copy fault.
// ROW-130 technique: the clipboard read both ways a writer would paste it (plain field, rich editor).
// cases: ROW-130 target=ROW-130-copying-from-the-box-while-highlights-show-puts-only-the-plain-text control=ROW-130-control-the-highlights-show-before-the-copy
//
// ROW-131 promise: on a touch phone with clipboard access refused, Copy text visibly selects the whole
//   text and the message names the long-press Copiar action (REQ-016 AMENDED arm 2 fail-if "on a
//   touch phone the message names only a keyboard shortcut"; A-048).
// ROW-131 wrong product: a fallback that always says "pulsa Ctrl+C", or that selects the text in a
//   box that has lost focus (no selection a phone shows).
// ROW-131 given: a touch phone context (the phone project's own; in Chromium a Pixel 7, in WebKit an
//   iPhone 13; Playwright's Firefox emulates no mobile device, so the other projects pay the row
//   there) whose browser refuses clipboard writes; when: Copy text is tapped; then: the box holds the
//   focus with its whole text selected, the message names Copiar and a press-and-hold action, and it
//   does not say the text was copied.
// ROW-131 controls: ROW-030's control (the fake refuses) runs in the same projects.
// ROW-131 technique: a device emulation per engine, the message read on its named element.
// cases: ROW-131 target=ROW-131-on-a-touch-phone-with-the-clipboard-refused-copy-text-selects-all-and-names-the-long-press-copiar control=ROW-030-control-the-browser-fake-refuses-a-clipboard-write

import { devices, expect, test, type Browser, type Page } from '@playwright/test';
import { accentPopulation, asActor, compose, el, enterOffer, freshMarker, freshRandom, openChecker, pressCheck, PRODUCT_URL, readHighlights, ROLES, type Rng } from './harness';
import {
  chooseSuggestion,
  claimsCopied,
  CMD_C,
  CTRL_C,
  isTouch,
  macSignals,
  openMenuByPointer,
  press,
  putOnClipboard,
  readClipboard,
  readMenu,
  readMessage,
  readOfferSelection,
  readOfferText,
  refuseClipboard,
  replacedAt,
  scratchPage,
  sprinkle,
} from './suggestions-helpers';

const WAIT_MS = 15_000;

function offer(rng: Rng) {
  const pop = accentPopulation();
  const a = rng.pick(pop);
  let b = rng.pick(pop);
  while (b.word === a.word || b.stripped.includes(a.stripped) || a.stripped.includes(b.stripped)) b = rng.pick(pop);
  const { text, placed } = compose(sprinkle(rng, [a.stripped, b.stripped]));
  return { text, pA: placed.find((p) => p.word === a.stripped)!, pB: placed.find((p) => p.word === b.stripped)! };
}

const copyButton = (page: Page) => el(page, ROLES.copy).first();

test('ROW-029-copy-text-puts-exactly-the-box-text-with-replacements-on-the-clipboard-and-confirms', async ({ page, context }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, pA, pB } = offer(rng);
  const sentinel = freshMarker();
  const scratch = await scratchPage(context);
  await putOnClipboard(scratch, sentinel);

  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-029: the check is answered').toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, text)).map((h) => h.word), { message: `ROW-029: both misspellings are highlighted (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual([pA, pB].sort((x, y) => x.start - y.start).map((q) => q.word));
  await openMenuByPointer(page, text, pA.start, 'ROW-029');
  const label = (await readMenu(page)).suggestions[0];
  expect(label, `ROW-029: "${pA.word}"'s menu holds a suggestion`).toBeTruthy();
  await chooseSuggestion(page, label, 'ROW-029');
  const expected = replacedAt(text, pA, label);
  await expect.poll(() => readOfferText(page), { message: 'ROW-029: the Replace is in the box', timeout: WAIT_MS }).toBe(expected);

  expect(claimsCopied(await readMessage(page)), 'ROW-029: before Copy text no message says the text was copied').toBe(false);
  expect((await readClipboard(scratch)).text, 'ROW-029: before Copy text the clipboard holds the sentinel').toBe(sentinel);
  await putOnClipboard(scratch, sentinel);

  await page.bringToFront();
  await press(page, copyButton(page));
  await expect.poll(() => readMessage(page), { message: 'ROW-029: Copy text says the text was copied', timeout: WAIT_MS }).toMatch(/copiad[oa]/i);
  expect(claimsCopied(await readMessage(page)), `ROW-029: the confirmation claims the copy — "${await readMessage(page)}"`).toBe(true);
  const box = await readOfferText(page);
  expect(box, 'ROW-029: the box holds the entered text with only the replaced word changed').toBe(expected);
  expect((await readClipboard(scratch)).text, `ROW-029: the clipboard holds exactly the box's text, the replacement included (seed ${rng.seed})`).toBe(box);
});

test('ROW-029-control-the-clipboard-probe-round-trips-a-sentinel', async ({ context }) => {
  asActor('anonymous');
  const sentinel = freshMarker();
  const scratch = await scratchPage(context);
  await putOnClipboard(scratch, sentinel);
  expect((await readClipboard(scratch)).text, 'ROW-029 control: the clipboard probe carries a fresh sentinel exactly').toBe(sentinel);
});

/** A page on the device kind the row needs, in this project's engine; null when the engine cannot emulate it. */
async function deviceFor(page: Page, browser: Browser, browserName: string, kind: 'keyboard' | 'phone'): Promise<Page | null> {
  const touch = await isTouch(page);
  if ((kind === 'phone') === touch) return page;
  if (kind === 'keyboard') return (await browser.newContext({ viewport: { width: 1280, height: 800 }, locale: 'es-ES', baseURL: PRODUCT_URL })).newPage();
  if (browserName === 'chromium') return (await browser.newContext({ ...devices['Pixel 7'], locale: 'es-ES', baseURL: PRODUCT_URL })).newPage();
  if (browserName === 'webkit') return (await browser.newContext({ ...devices['iPhone 13'], locale: 'es-ES', baseURL: PRODUCT_URL })).newPage();
  return null;
}

test('ROW-030-with-the-clipboard-refused-copy-text-selects-all-and-names-ctrl-c-without-claiming-a-copy', async ({ page, browser, browserName }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text } = offer(rng);
  const p = (await deviceFor(page, browser, browserName, 'keyboard'))!;
  await refuseClipboard(p);
  await openChecker(p);
  await enterOffer(p, text);
  const mac = await macSignals(p);
  const shortcut = mac.platform && mac.userAgent ? CMD_C : !mac.platform && !mac.userAgent ? CTRL_C : new RegExp(`${CTRL_C.source}|${CMD_C.source}`, 'i');
  expect(await readMessage(p), 'ROW-030: before Copy text no message names the shortcut').not.toMatch(shortcut);

  await press(p, copyButton(p));
  await expect
    .poll(() => readMessage(p), { message: `ROW-030: Copy text tells the writer to press ${mac.platform && mac.userAgent ? 'Cmd+C' : 'Ctrl+C'} (platform Mac: ${mac.platform}, user agent Mac: ${mac.userAgent})`, timeout: WAIT_MS })
    .toMatch(shortcut);
  const message = await readMessage(p);
  expect((await readOfferSelection(p)).selected, 'ROW-030: Copy text selects all the text in the box').toBe(text);
  expect(claimsCopied(message), `ROW-030: the message does not claim the text was copied — "${message}"`).toBe(false);
});

test('ROW-030-control-the-browser-fake-refuses-a-clipboard-write', async ({ page }) => {
  asActor('anonymous');
  await refuseClipboard(page);
  await openChecker(page);
  const refused = await page.evaluate(async () => {
    const exec = document.execCommand('copy');
    let api = 'absent';
    const c = (navigator as Navigator & { clipboard?: Clipboard }).clipboard;
    if (c) api = await c.writeText('x').then(() => 'written', (e: DOMException) => e.name);
    return { exec, api };
  });
  expect(refused.exec, 'ROW-030 control: execCommand("copy") is refused').toBe(false);
  expect(['absent', 'NotAllowedError'], `ROW-030 control: navigator.clipboard.writeText is refused (${refused.api})`).toContain(refused.api);
});

test('ROW-130-copying-from-the-box-while-highlights-show-puts-only-the-plain-text', async ({ page, context }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text } = offer(rng);
  const sentinel = freshMarker();
  const scratch = await scratchPage(context);
  await putOnClipboard(scratch, sentinel);

  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-130: the check is answered').toBe(200);
  await expect.poll(async () => (await readHighlights(page, text)).length, { message: `ROW-130: the highlights show before the copy (seed ${rng.seed})`, timeout: WAIT_MS }).toBe(2);

  await page.bringToFront();
  await el(page, ROLES.offer).first().focus();
  await page.keyboard.press('ControlOrMeta+A');
  await page.keyboard.press('ControlOrMeta+C');
  const got = await readClipboard(scratch);
  expect(got.text, `ROW-130: the clipboard's plain text is exactly the box's text (seed ${rng.seed})`).toBe(text);
  expect(got.richFormatted, `ROW-130: pasted into a rich editor, the copy brings no formatting — ${got.richHtml}`).toBe(false);
});

test('ROW-130-control-the-highlights-show-before-the-copy', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text } = offer(rng);
  await openChecker(page);
  await enterOffer(page, text);
  expect((await pressCheck(page)).status, 'ROW-130 control: the check is answered').toBe(200);
  await expect.poll(async () => (await readHighlights(page, text)).length, { message: 'ROW-130 control: the two highlights show', timeout: WAIT_MS }).toBe(2);
});

const LONG_PRESS = /(mant[eé]n|mantener|mantenga|deja(r)?\s+pulsad|pulsaci[oó]n\s+(larga|prolongada)|presiona\s+y\s+mant|toca\s+y\s+mant|pulsa\s+y\s+mant)/i;

test('ROW-131-on-a-touch-phone-with-the-clipboard-refused-copy-text-selects-all-and-names-the-long-press-copiar', async ({ page, browser, browserName }) => {
  asActor('anonymous');
  const p = await deviceFor(page, browser, browserName, 'phone');
  test.skip(p === null, "Playwright's Firefox emulates no mobile device; the phone, Chromium and WebKit projects pay ROW-131");
  const rng = freshRandom();
  const { text } = offer(rng);
  await refuseClipboard(p!);
  await openChecker(p!);
  await enterOffer(p!, text);
  expect(await readMessage(p!), 'ROW-131: before Copy text no message names Copiar').not.toMatch(/Copiar/);

  await copyButton(p!).tap({ timeout: WAIT_MS });
  await expect.poll(() => readMessage(p!), { message: 'ROW-131: Copy text shows a message naming the Copiar action', timeout: WAIT_MS }).toMatch(/Copiar/);
  const message = await readMessage(p!);
  const sel = await readOfferSelection(p!);
  expect(sel.selected, 'ROW-131: Copy text selects the whole text').toBe(text);
  expect(sel.focused, 'ROW-131: the box holds the focus, so the selection is visible on the phone').toBe(true);
  expect(message, 'ROW-131: the message names the Copiar action').toMatch(/Copiar/);
  expect(message, 'ROW-131: the message names pressing and holding the text').toMatch(LONG_PRESS);
  expect(claimsCopied(message), `ROW-131: the message does not claim the text was copied — "${message}"`).toBe(false);
});
